                if step > 0:
                    exp_list = lst[start:stop:step]
                    if got != exp_list:
                        record("vs-list", (tag, start, stop, step, got, exp_list, lst))
    # integer indices
    for i in list(range(-n-3, n+4)) + [None]:
        if i is None: continue
