        if got != exp:
            record("index()", (tag, v, got, exp, lst))
    # iteration / reversed / contains / len
    if list(reversed(s)) != list(reversed(lst)): record("reversed", (tag, lst))
    if set(s) != set(lst) or len(s) != len(lst): record("misc", (tag, lst))

