import math, random, humanize
from humanize.number import _format_not_finite

def pre(value, unit='', precision=3):
    if not math.isfinite(value): return _format_not_finite(value)
    exponent = math.floor(math.log10(abs(value))) if value != 0 else 0
    if exponent >= 33 or exponent < -30:
        return humanize.scientific(value, precision-1) + unit
    old = exponent//3*3
    value /= 10**old
    digits = int(max(0, precision - exponent % 3 - 1))
    if exponent < 30 and round(abs(value), digits) >= 1000:
        exponent += 3 - exponent % 3
        nb = exponent//3*3
        value /= 10**(nb-old)
        digits = int(max(0, precision - exponent % 3 - 1))
    if exponent >= 3:
        o = 'kMGTPEZYRQ'[exponent//3-1]
    elif exponent < 0:
        o = 'mμnpfazyrq'[(-exponent-1)//3]
    else:
        o = ''
    v = format(value, f'.{digits}f')
    sp = '' if not (unit or o) or unit in ('°','′','″') else ' '
