function base (v1, v2) { // shared preamble -> null or [high, low, highHasPre, lowHasPre]
  const comparison = v1.compare(v2)
  if (comparison === 0) return null
  const v1Higher = comparison > 0
  const high = v1Higher ? v1 : v2
  const low = v1Higher ? v2 : v1
  return [high, low, !!high.prerelease.length, !!low.prerelease.length]
}
function tail (v1, v2, prefix) {
  if (v1.major !== v2.major) return prefix + 'major'
  if (v1.minor !== v2.minor) return prefix + 'minor'
  if (v1.patch !== v2.patch) return prefix + 'patch'
  return 'prerelease'
}

const cands = {
