    parts.push(op + rnd(tuples) + rnd(pres))
  }
  let r = parts.join(' ')
  if (Math.random() < 0.2) r += ' || ' + rnd(tuples) + rnd(pres)
  return r
}

// candidate versions derived from a range string
function candidates(str) {
  const out = new Set()
  const ms = str.match(/\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?/g) || []
  for (const m of ms) {
    const sv = semver.valid(m)
    if (!sv) continue
    const S = new semver.SemVer(sv)
    out.add(S.version)
    const base = `${S.major}.${S.minor}.${S.patch}`
    out.add(base)
    out.add(base+'-0')
    out.add(base+'-1')
    out.add(base+'-rc')
    out.add(base+'-rc.5')
    out.add(base+'-rc.6')
    out.add(base+'-alpha')
    if (S.prerelease.length) {
      const p = S.prerelease.slice()
      if (typeof p[p.length-1] === 'number') p[p.length-1] = p[p.length-1]+1
      else p.push(1)
      out.add(`${base}-${p.join('.')}`)
    }
    const np = new semver.SemVer(base)
    out.add(`${S.major}.${S.minor}.${np.patch+1}`)
    out.add(`${S.major}.${S.minor}.${np.patch+1}-0`)
    out.add(`${S.major}.${S.minor+1||1}.${np.patch}`)
  }
  return [...out].map(v => semver.valid(v)).filter(Boolean)
}

function parseSafe(r, opts) { try { return new Range(r, opts) } catch(e) { return null } }

